contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount: amount of Wei to send when calling Deposit
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // must have funds to send
        require(address(this).balance >= depositAmount, "insufficient balance to deposit");

        // observe before-values
        uint before_map = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint before_eth = address(c).balance;

        // perform Deposit and record whether it reverted
        bool didRevert;
        c.Deposit{value: depositAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // observe after-values
        uint after_map = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint after_eth = address(c).balance;

        // If Deposit did not revert, mapping balance must have increased by exactly depositAmount
        // and contract's ETH must have increased by at least depositAmount (it may round up due to external factors but cannot shrink)
        assert(didRevert || (after_map == before_map + depositAmount && after_eth >= before_eth + depositAmount));
    }

    // receive to accept refunds if any
    receive() external payable { }
}

