// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint256 before_map;
        try c.balances(address(this)) returns (uint256 __r) { before_map = __r; } catch { return; }
        uint before_eth = address(c).balance;
        bool didRevert;
        try c.Deposit{value: depositAmount}() {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        uint256 after_map;
        try c.balances(address(this)) returns (uint256 __r) { after_map = __r; } catch { return; }
        uint after_eth = address(c).balance;
        assertTrue(didRevert || (after_map == before_map + depositAmount && after_eth >= before_eth + depositAmount));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable { }
}
